container_args:
set -uo pipefail
# Build and dependency fact sheet, run inside the Java agent image (project read-only under /workspace,
# persistent Maven repository under /cache). Network is needed for update lookups; without it the
# Maven facts are NICHT GEMESSEN and only the POM facts remain.
BUILD_DIR="/workspace/{{ java_build_dir }}"
WORK=$(mktemp -d)
echo '## FAKTENBLATT'
echo '# Measured deterministically (Maven versions/dependency plugin, POM analysis). TREFFER lines are candidates.'
if [ ! -f "$BUILD_DIR/pom.xml" ]; then
  echo "NICHT GEMESSEN: dependency_updates (no pom.xml in {{ java_build_dir }})"
  exit 0
fi
cd "$BUILD_DIR"
M="mvn -B -ntp -Dmaven.repo.local=/cache/m2"
IGNORE='(?i).*[.-](alpha|beta|m|rc|cr|snapshot|preview|ea|b|pr)[.-]?[0-9]*$'
VP=org.codehaus.mojo:versions-maven-plugin:2.18.0
$M $VP:display-dependency-updates -Dmaven.version.ignore="$IGNORE" -DprocessDependencyManagementTransitive=false \
   -Dversions.outputFile="$WORK/deps.txt" -DoutputEncoding=UTF-8 > "$WORK/deps.log" 2>&1; echo "$?" > "$WORK/deps.rc"
$M $VP:display-plugin-updates -Dmaven.version.ignore="$IGNORE" \
   -Dversions.outputFile="$WORK/plugins.txt" -DoutputEncoding=UTF-8 > "$WORK/plugins.log" 2>&1; echo "$?" > "$WORK/plugins.rc"
$M $VP:display-parent-updates -Dmaven.version.ignore="$IGNORE" -DallowMajorUpdates=true \
   -Dversions.outputFile="$WORK/parent.txt" -DoutputEncoding=UTF-8 > "$WORK/parent.log" 2>&1; echo "$?" > "$WORK/parent.rc"
$M org.apache.maven.plugins:maven-dependency-plugin:3.8.1:tree -Dverbose -DoutputFile="$WORK/tree.txt" > "$WORK/tree.log" 2>&1; echo "$?" > "$WORK/tree.rc"
python3 - "$WORK" "$BUILD_DIR" <<'PYEOF'
import os, re, sys
import xml.etree.ElementTree as ET

work, build_dir = sys.argv[1], sys.argv[2]
CAP = 40


def read(name):
    p = os.path.join(work, name)
    return open(p, encoding='utf-8', errors='replace').read() if os.path.exists(p) else ''


def rc(name):
    v = read(name + '.rc').strip()
    return int(v) if v.isdigit() else -1


def updates(text):
    """(artifact, current, latest) from versions-plugin output; entries may wrap onto a second line."""
    out, pending = [], None
    for line in text.splitlines():
        line = re.sub(r'^\[INFO\]\s?', '', line).rstrip()
        m = re.match(r'^\s+([\w.\-]+:[\w.\-]+)\s*\.*\s*(\S+)\s+->\s+(\S+)\s*$', line)
        if m:
            out.append(m.groups()); pending = None; continue
        m = re.match(r'^\s+([\w.\-]+:[\w.\-]+)\s*\.*\s*$', line)
        if m:
            pending = m.group(1); continue
        m = re.match(r'^\s+(\S+)\s+->\s+(\S+)\s*$', line)
        if m and pending:
            out.append((pending, m.group(1), m.group(2))); pending = None
    return out


def jump(cur, new):
    a = re.findall(r'\d+', cur)[:3]
    b = re.findall(r'\d+', new)[:3]
    a += ['0'] * (3 - len(a)); b += ['0'] * (3 - len(b))
    if a[0] != b[0]:
        return 'major'
    if a[1] != b[1]:
        return 'minor'
    return 'patch'


def emit(kind, rows):
    print('FAKT %s_count: %d' % (kind, len(rows)))
    return [(kind, r) for r in rows]


hits = []
for name, kind, label in (('deps', 'dependency_update', 'Dependency'), ('plugins', 'plugin_update', 'Plugin')):
    if rc(name) != 0:
        print('NICHT GEMESSEN: %s_count (mvn versions Exit %d: %s)' % (kind, rc(name), (read(name + '.log').strip().splitlines() or ['no log'])[-1][:160]))
        continue
    seen, rows = set(), []
    for art, cur, new in updates(read(name + '.txt') or read(name + '.log')):
        if (art, cur, new) in seen:
            continue
        seen.add((art, cur, new))
        rows.append((jump(cur, new), '%s %s -> %s (%s)' % (art, cur, new, jump(cur, new))))
    rows.sort(key=lambda r: {'major': 0, 'minor': 1, 'patch': 2}[r[0]])
    for level in ('major', 'minor', 'patch'):
        print('FAKT %s_%s: %d' % (kind, level, sum(1 for r in rows if r[0] == level)))
    hits += emit(kind, [t for _, t in rows])

if rc('parent') == 0:
    for art, cur, new in updates(read('parent.txt') or read('parent.log')):
        hits += emit('parent_update', ['%s %s -> %s (%s)' % (art, cur, new, jump(cur, new))])
        break
    else:
        print('FAKT parent_update_count: 0')
else:
    print('NICHT GEMESSEN: parent_update_count (mvn Exit %d)' % rc('parent'))

if rc('tree') == 0:
    conflicts = {}
    for line in read('tree.txt').splitlines():
        m = re.search(r'([\w.\-]+:[\w.\-]+):\w+:([\w.\-]+)(?::\w+)? - omitted for conflict with ([\w.\-]+)', line)
        if m:
            conflicts.setdefault(m.group(1), set()).add('%s instead of %s' % (m.group(3), m.group(2)))
    hits += emit('dependency_conflict', ['%s: %s' % (k, ', '.join(sorted(v))) for k, v in sorted(conflicts.items())])
else:
    print('NICHT GEMESSEN: dependency_conflict_count (mvn dependency:tree Exit %d)' % rc('tree'))

# POM analysis (no network needed)
pom_rows = {'snapshot_dependency': [], 'version_range': [], 'plugin_without_version': [], 'insecure_repository': [],
            'test_library_compile_scope': []}
TEST_LIBS = re.compile(r'^(junit|org\.junit.*|org\.mockito.*|org\.assertj|org\.hamcrest|com\.h2database|org\.testcontainers.*|io\.rest-assured)$')
java_version = boot_version = None
for dirpath, dirnames, filenames in os.walk(build_dir):
    dirnames[:] = [d for d in dirnames if not d.startswith(('.', 'target')) and d not in ('node_modules', 'src')]
    if 'pom.xml' not in filenames:
        continue
    pom = os.path.join(dirpath, 'pom.xml')
    rel = os.path.relpath(pom, '/workspace')
    try:
        root = ET.parse(pom).getroot()
    except ET.ParseError as e:
        print('NICHT GEMESSEN: pom_analysis (%s not readable: %s)' % (rel, e))
        continue
    ns = {'m': root.tag.split('}')[0].strip('{')} if root.tag.startswith('{') else {}
    q = (lambda p: p.replace('/', '/m:').replace('//m:', '//m:')) if ns else (lambda p: p)
    def find_all(path):
        return root.findall(('m:' + path.replace('/', '/m:')) if ns else path, ns)
    def text(el, tag):
        c = el.find(('m:' + tag) if ns else tag, ns)
        return c.text.strip() if c is not None and c.text else ''
    parent = root.find('m:parent' if ns else 'parent', ns)
    if parent is not None and text(parent, 'artifactId') == 'spring-boot-starter-parent':
        boot_version = boot_version or text(parent, 'version')
    props = root.find('m:properties' if ns else 'properties', ns)
    if props is not None:
        for p in props:
            tag = p.tag.split('}')[-1]
            if tag in ('java.version', 'maven.compiler.release', 'maven.compiler.target') and p.text and not java_version:
                java_version = p.text.strip()
    for dep in find_all('dependencies/dependency') + find_all('dependencyManagement/dependencies/dependency'):
        ga = '%s:%s' % (text(dep, 'groupId'), text(dep, 'artifactId'))
        v = text(dep, 'version')
        if v.endswith('-SNAPSHOT'):
            pom_rows['snapshot_dependency'].append('%s %s %s' % (rel, ga, v))
        if re.match(r'^[\[(].*,.*[\])]$', v) or v in ('LATEST', 'RELEASE'):
            pom_rows['version_range'].append('%s %s %s' % (rel, ga, v))
        if TEST_LIBS.match(text(dep, 'groupId')) and text(dep, 'scope') not in ('test', 'provided') and dep in find_all('dependencies/dependency'):
            pom_rows['test_library_compile_scope'].append('%s %s without scope test' % (rel, ga))
    for plugin in find_all('build/plugins/plugin'):
        if not text(plugin, 'version') and not (parent is not None and text(plugin, 'groupId') in ('', 'org.apache.maven.plugins', 'org.springframework.boot')):
            pom_rows['plugin_without_version'].append('%s %s:%s' % (rel, text(plugin, 'groupId'), text(plugin, 'artifactId')))
    for repo in find_all('repositories/repository') + find_all('pluginRepositories/pluginRepository'):
        if text(repo, 'url').startswith('http://'):
            pom_rows['insecure_repository'].append('%s %s' % (rel, text(repo, 'url')))
print('FAKT java_version: %s' % (java_version or 'not set'))
print('FAKT spring_boot_version: %s' % (boot_version or 'no spring-boot-starter-parent'))
for kind, rows in pom_rows.items():
    hits += emit(kind, rows)
print('')
per_kind = {}
for kind, row in hits:
    per_kind.setdefault(kind, []).append(row)
for kind, rows in per_kind.items():
    for r in rows[:CAP]:
        print('TREFFER %s: %s' % (kind, r))
    if len(rows) > CAP:
        print('# %d more %s hits not listed' % (len(rows) - CAP, kind))
print('')
print('## PFLICHTFELDER')
print('PFLICHT-FAKTEN: dependency_update_count plugin_update_count dependency_conflict_count')
PYEOF
rm -rf "$WORK"
